INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('QE-E-01', 'QE', 'easy', 'plain', 'Solve $x^2-5x+6=0$.', 'solution_set', '2, 3', '[]', 'none', NULL, '[{"explanation": "Factor the trinomial.", "latex": "(x-2)(x-3)=0"}, {"explanation": "Set each factor to zero.", "latex": "x=2 \\text{ or } x=3"}]', 'grade9_quadratic_equations_intro.pdf', 'sha256:7ac50938ac22e2fdc3bfc02a4d21b73e300b22bacd49d03fc5d78114df76ac4f', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('QE-M-01', 'QE', 'medium', 'word', 'The sum of a number and its square is $30$. Find all such numbers.', 'solution_set', '-6, 5', '[]', 'none', NULL, '[{"explanation": "Let the number be x. Write the equation.", "latex": "x+x^2=30"}, {"explanation": "Move everything to one side and factor.", "latex": "x^2+x-30=0,\\quad (x+6)(x-5)=0"}, {"explanation": "Set each factor to zero.", "latex": "x=-6 \\text{ or } x=5"}]', 'grade9_quadratic_equations_intro.pdf', 'sha256:12ac0948de903ad9cd6fad3f037f3535ed885e6f318cd6b8a13ed403cf1d2549', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('FP-E-01', 'FP', 'easy', 'plain', 'Factor completely: $x^2+7x+12$.', 'expression', '(x+3)(x+4)', '[]', 'factored', NULL, '[{"explanation": "Find two numbers that multiply to 12 and add to 7: 3 and 4.", "latex": "3\\cdot 4=12,\\quad 3+4=7"}, {"explanation": "Write the two binomial factors.", "latex": "(x+3)(x+4)"}]', 'grade8_factoring_trinomials.pdf', 'sha256:5bd8f0f076af927090fa75ce094a428c2d6851627e0d14d6837baee3c82a604c', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('SP-E-01', 'SP', 'easy', 'plain', 'Expand and simplify: $(x+3)(x-5)$.', 'expression', 'x^2-2x-15', '[]', 'expanded', NULL, '[{"explanation": "Multiply each term of the first factor by each term of the second.", "latex": "x^2-5x+3x-15"}, {"explanation": "Combine like terms.", "latex": "x^2-2x-15"}]', 'grade7_special_products.pdf', 'sha256:33c8c1c30232f70cea73570f0958d9a2e9b1defc9f27fbc16fb8129a8cd352ac', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('FD-E-01', 'FD', 'easy', 'plain', 'Write $\frac{18}{24}$ in lowest terms.', 'number', '\frac{3}{4}', '[]', 'lowest_terms', NULL, '[{"explanation": "Find the greatest common factor of 18 and 24, which is 6.", "latex": "\\gcd(18,24)=6"}, {"explanation": "Divide the numerator and denominator by 6.", "latex": "\\frac{18\\div 6}{24\\div 6}=\\frac{3}{4}"}]', 'grade6_fractions_division.pdf', 'sha256:b8370cacc07ae07c83d568e848892a8f92e4c6f5b604006f0841b3f78aa37009', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('SLE-E-01', 'SLE', 'easy', 'plain', 'Solve the system: $x+y=10$ and $x-y=2$.', 'ordered_pair', '(6, 4)', '[]', 'none', NULL, '[{"explanation": "Add the two equations to eliminate y.", "latex": "2x=12 \\Rightarrow x=6"}, {"explanation": "Substitute x = 6 into the first equation.", "latex": "6+y=10 \\Rightarrow y=4"}]', 'grade8_systems_equations_algebraic.pdf', 'sha256:da3b6c9fa59091d9552c533ebfdb795f472f770e0987fb513dabce1f259575e8', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('SLE-M-01', 'SLE', 'medium', 'word', 'The sum of two numbers is $14$ and their difference is $4$. Find the numbers, written as (larger, smaller).', 'ordered_pair', '(9, 5)', '[]', 'none', NULL, '[{"explanation": "Let x be the larger number and y the smaller.", "latex": "x+y=14,\\quad x-y=4"}, {"explanation": "Add the equations.", "latex": "2x=18 \\Rightarrow x=9"}, {"explanation": "Substitute back to find y.", "latex": "9+y=14 \\Rightarrow y=5"}]', 'grade8_systems_equations_algebraic.pdf', 'sha256:1f21404d014b62418c20e599861801caae6ab2533046eb23df5eec258b35bbff', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('L2V-E-01', 'L2V', 'easy', 'plain', 'Find the point on the line $y=3x-2$ whose $x$-coordinate is $4$.', 'ordered_pair', '(4, 10)', '[]', 'none', NULL, '[{"explanation": "Substitute x = 4 into the equation.", "latex": "y=3(4)-2"}, {"explanation": "Compute y.", "latex": "y=10"}]', 'grade8_linear_equations_two_var.pdf', 'sha256:741b9e8a9d2c7076d16e927022dbbc2308b2cce9813fcb529a08521b3b330232', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('L2V-E-02', 'L2V', 'easy', 'plain', 'Write $2x+y=10$ in slope-intercept form.', 'equation', 'y=-2x+10', '[]', 'slope_intercept', NULL, '[{"explanation": "Subtract 2x from both sides to isolate y.", "latex": "y=-2x+10"}]', 'grade8_slope_intercept.pdf', 'sha256:9da95baf0a725ee26ec1cb9887ce9584ff9d7f3bea48ef38e20a5f8f771b2800', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('L2V-M-01', 'L2V', 'medium', 'word', 'A taxi fare starts at 3 pesos and rises steadily to 7 pesos after $2$ km. Write the fare $y$ for $x$ km in slope-intercept form.', 'equation', 'y=2x+3', '[]', 'slope_intercept', NULL, '[{"explanation": "The fare at 0 km is the y-intercept.", "latex": "b=3"}, {"explanation": "Find the slope from the two points (0, 3) and (2, 7).", "latex": "m=\\frac{7-3}{2-0}=2"}, {"explanation": "Write y = mx + b.", "latex": "y=2x+3"}]', 'grade8_slope_intercept.pdf', 'sha256:dee1d251a661728736eba2bc9688d07075d08a915bb8b535f77debfa4de809d5', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('L2V-H-01', 'L2V', 'hard', 'plain', 'Write the equation of the line with slope $\frac{1}{2}$ and $y$-intercept $-4$.', 'equation', 'y=\frac{1}{2}x-4', '[]', 'slope_intercept', NULL, '[{"explanation": "Substitute m = 1/2 and b = -4 into y = mx + b.", "latex": "y=\\frac{1}{2}x-4"}]', 'grade8_slope_intercept.pdf', 'sha256:8b40de38766c7f0f25d19bdb03a60ded8dbf0b90d1d1aa1eca7425fa40b0e6dc', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('RPP-E-01', 'RPP', 'easy', 'word', 'Maria scored $45$ out of $60$ items on a quiz. What percent of the items did she answer correctly?', 'number', '75', '[]', 'none', '%', '[{"explanation": "Write the score as a fraction of the total.", "latex": "\\frac{45}{60}=\\frac{3}{4}"}, {"explanation": "Multiply by 100 to get a percent.", "latex": "\\frac{3}{4}\\times 100=75"}]', 'grade6_percent.pdf', 'sha256:422a3f510968733dee1d939c4f45d0bd65040396321b3273af096267bf22ca2d', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('RPP-M-01', 'RPP', 'medium', 'word', 'A bus travels $270$ km in $4.5$ hours at a steady speed. What is its average speed?', 'number', '60', '[]', 'none', 'km/h', '[{"explanation": "Speed is distance divided by time.", "latex": "\\text{speed}=\\frac{270}{4.5}"}, {"explanation": "Divide.", "latex": "\\frac{270}{4.5}=60"}]', 'grade6_rate_speed_distance.pdf', 'sha256:72e053a225eb3266acb263e342d8568e87720ce2b4f82829f2627a6093d1af84', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('RER-M-01', 'RER', 'medium', 'plain', 'Simplify $\sqrt{18x^2}$, where $x\ge 0$.', 'expression', '3x\sqrt{2}', '[]', 'simplest_radical', NULL, '[{"explanation": "Pull out the perfect squares 9 and x^2.", "latex": "\\sqrt{18x^2}=\\sqrt{9\\cdot 2\\cdot x^2}"}, {"explanation": "Take the square roots of the perfect squares.", "latex": "3x\\sqrt{2}"}]', 'grade9_simplifying_radicals.pdf', 'sha256:6d7d116201bff6c4280733605201eca95f5eb9f4bcb61458d36f88ef5d4fe253', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('PE-M-01', 'PE', 'medium', 'plain', 'Find all solutions of $x^3-6x^2+11x-6=0$.', 'solution_set', '1, 2, 3', '[]', 'none', NULL, '[{"explanation": "Test x = 1 using the rational root theorem; it is a root.", "latex": "1-6+11-6=0"}, {"explanation": "Divide out (x-1) and factor the quadratic quotient.", "latex": "(x-1)(x^2-5x+6)=(x-1)(x-2)(x-3)"}, {"explanation": "Set each factor to zero.", "latex": "x=1,\\ 2,\\ 3"}]', 'grade10_polynomial_equations.pdf', 'sha256:77aea4385da0bc9b03d46555a112246eba44382062a295002d1b3d133a2c6d96', '2026-10-28T15:10:10.753495+00:00') ON CONFLICT DO NOTHING;
